        if (n * d) % 2 != 0:
            return None
        adj_matrix = [[0] * n for _ in range(n)]
        edges_added = set()

        for i in range(n):
            neighbors = random.sample(range(n), d)
            for j in neighbors:
                if i < j and (i, j) not in edges_added:
                    adj_matrix[i][j] = 1
                    adj_matrix[j][i] = 1
                    edges_added.add((i, j))

        return adj_matrix

    def gromov_witten_invariant(adj_matrix):
        n = len(adj_matrix)
        count = 0

        for i in range(n):
            for j in range(i + 1, n):
                if adj_matrix[i][j] == 1:
                    count += 1

        return Fraction(count, (n * (n - 1)) // 2)

    def communication_complexity_rank(adj_matrix):
        n = len(adj_matrix)
        rank = 0

        for i in range(n):
            for j in range(i + 1, n):
                if adj_matrix[i][j] == 1:
                    rank += 1

        return rank

